    function clear(id) {
      const node = document.getElementById(id);
      node.textContent = '';
      node.className = 'cor-field-feedback';
    }
    function markStale(event) {
      const target = event.target;
      if (feedbackByInput.has(target.id)) {
        target.removeAttribute('aria-invalid');
        clear(feedbackByInput.get(target.id));
      }
      if (feedbackByName.has(target.name)) clear(feedbackByName.get(target.name));
      if (!overall.hidden) overall.textContent = 'Modificaste una respuesta. Presiona «Comprobar mis respuestas» para actualizar la revisión.';
    }
    numericFields.forEach(f => document.getElementById(f.id).addEventListener('input', markStale));
    choiceFields.forEach(f => document.querySelectorAll('input[name="' + f.name + '"]').forEach(el => el.addEventListener('change', markStale)));
    button.addEventListener('click', function () {
      let correct = 0;
      const total = numericFields.length + choiceFields.length;
      numericFields.forEach(field => {
        const input = document.getElementById(field.id);
        const parsed = field.key === 'p' ? pCorrect(input.value, ref.p) : parseLocaleNumber(input.value);
        if (parsed.kind === 'empty') {
          report(field.msg, 'Ingresa un valor para comprobarlo.', false, input);
        } else if (parsed.kind === 'invalid') {
          report(field.msg, 'Escribe un resultado válido (coma o punto decimal, sin separadores de miles).', false, input);
        } else if (field.key === 'p' ? parsed.ok : approx(field.key, parsed.value, ref[field.key])) {
          report(field.msg, '✓ Coincide con el resultado esperado.', true, input);
          correct++;
        } else if (field.key === 'rho' && approx('rho', parsed.value, ref.r)) {
          report(field.msg, 'Ese valor corresponde a Pearson. Revisa qué coeficiente es adecuado para estas variables.', false, input);
        } else if (field.key === 'rho' && approx('rho', parsed.value, -ref.rho)) {
          report(field.msg, 'La magnitud es correcta, pero revisa el signo.', false, input);
        } else {
          report(field.msg, 'Revisa este resultado. ' + field.hint, false, input);
        }
      });
      choiceFields.forEach(field => {
        const selected = document.querySelector('input[name="' + field.name + '"]:checked');
        if (!selected) {
          report(field.msg, 'Selecciona una opción para verificarla.', false);
        } else if (selected.value === field.expected) {
          report(field.msg, field.ok, true);
          correct++;
        } else {
          report(field.msg, field.hint, false);
        }
      });
      document.querySelectorAll('.cor-answer-layout').forEach(layout => {
        layout.classList.add('cor-expanded');
        const model = layout.querySelector('.cor-model-panel');
        if (model) model.hidden = false;
      });
      overall.hidden = false;
      overall.textContent = correct === total
        ? '¡Muy bien! Los ' + total + ' resultados verificables coinciden con los valores esperados. Compara ahora tu código, gráfico e interpretaciones con los modelos junto a cada pregunta.'
        : 'Coinciden ' + correct + ' de ' + total + ' resultados verificables. Revisa las pistas y vuelve a comprobar. Ya puedes comparar tus respuestas con los modelos junto a cada pregunta. No se asigna una nota.';
    });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
  else start();
}());
</script>
```


## 2. Matrices de correlación

La segunda parte de esta sesión ejercitaremos el cómo estimar e interpretar una matriz de correlaciones. En este caso, trabajaremos con una versión preparada de la encuesta CASEN 2024.

Carga la base en R:



::: {.cell}

```{.r .cell-code}
load(url("https://github.com/cursos-metodos-facso/datos-ejemplos/raw/main/casen_2024_prep.RData"))
```
:::


La base de datos se contiene las siguientes variables:

| Variable | Qué mide | Escala |
|---|---|---|
| `escolaridad` | Años de escolaridad | Continua |
| `horas_trabajo` | Horas trabajadas habitualmente por semana (solo personas que trabajan) | Continua |
| `sexo` | Sexo del respondente | 0 = hombre, 1 = mujer |
| `barrio_peleas` | Frecuencia con que ha presenciado personas peleando o amenazándose en su barrio | 1 = Nunca ... 4 = Siempre |
| `barrio_ruidos` | Frecuencia con que ha presenciado contaminación acústica o ruidos molestos en su barrio | 1 = Nunca ... 4 = Siempre |

### Ejercicio

**1)** Estime la matriz de correlaciones entre las variables `escolaridad`, `horas_trabajo`, `sexo`, `barrio_peleas` y `barrio_ruidos`

**2)** Reporte la correlación entre las siguientes variables, indicando si se encontró significancia estadística, el nivel de confianza con que se puede rechazar la hipótesis nula (en caso de que corresponda) y una interpretación sustantiva:

- `barrio_peleas` y `barrio_ruidos`

- `sexo` y `horas_trabajo`

- `escolaridad` y `barrios_peleas`

**3)** ¿Qué decisión tomó sobre los casos perdidos en el cálculo de la matriz? Justifique 


**4)** ¿Cómo se denomina el tipo de correlación que se estima entre `sexo` y `horas_trabajo`?


